cat > /tmp/repro.py <<'EOF'
import re
from rich.ansi import re_ansi

def test_regex():
    texts = [
        "Hello\x1b7World",
        "Hello\x1b8World",
        "Hello\x1b0World",
        "Hello\x1b?World",
    ]
    for text in texts:
        match = re_ansi.search(text)
        if match:
            print(f"Text: {repr(text)} Match: {repr(match.group(0))}")
        else:
            print(f"Text: {repr(text)} Match: None")

if __name__ == "__main__":
    test_regex()
EOF
